pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;
    function setUp() public { c = new Reentrancy_bonus(); }

    function testFuzz_property(address fuzzRecipient) public {
        Reverter rev = new Reverter();

        address recipient = address(rev);

        bool ok;
        try c.getFirstWithdrawalBonus(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false);
    }
}

contract Reverter {
    fallback() external payable {
        revert("no accept");
    }
    receive() external payable {
        revert("no accept");
    }
}
